// Baked NASA Mars Trek Gale Crater DEM Heightmap (256x256)
const B64 = "";
let cachedGrid: Uint8Array | null = null;

export function getMarsTrekDemGrid(): Uint8Array {
  if (!cachedGrid) {
    const binary = atob(B64);
    const len = binary.length;
    cachedGrid = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      cachedGrid[i] = binary.charCodeAt(i);
    }
  }
  return cachedGrid;
}
